_FALLBACK_WORKFLOW_ENGINE = '''\
"""Approval workflow state machine — generated by AetherOS (fallback)."""
from __future__ import annotations
import enum
import logging
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)


class WorkflowState(str, enum.Enum):
    DRAFT = "draft"
    PENDING_APPROVAL = "pending_approval"
    APPROVED = "approved"
    REJECTED = "rejected"
    CANCELLED = "cancelled"
    COMPLETED = "completed"


@dataclass
class WorkflowTransition:
    from_state: str
    to_state: str
    actor: str          # role that may trigger this transition
    condition: str = ""
    action: str = ""    # side-effect to trigger (e.g. "send_email")


class WorkflowEngine:
    """State machine engine for {domain} approval workflows."""

    WORKFLOWS: Dict[str, List[WorkflowTransition]] = {{
        "default": [
            WorkflowTransition("draft", "pending_approval", "Staff", action="notify_manager"),
            WorkflowTransition("pending_approval", "approved", "Manager", action="notify_submitter"),
            WorkflowTransition("pending_approval", "rejected", "Manager", action="notify_submitter"),
            WorkflowTransition("approved", "completed", "Admin"),
            WorkflowTransition("*", "cancelled", "Admin"),
        ],
    }}

    async def transition(
        self,
        db: Any,
        entity_type: str,
        entity_id: Any,
        new_state: str,
        actor_role: str,
        actor_id: Any,
    ) -> bool:
        """Apply a workflow transition. Returns True if successful."""
        transitions = self.WORKFLOWS.get(entity_type, self.WORKFLOWS.get("default", []))
        allowed = [
            t for t in transitions
            if t.actor in (actor_role, "Admin", "*")
            and t.to_state == new_state
        ]
        if not allowed:
            logger.warning(
                "WorkflowEngine: %s cannot transition %s to %s",
                actor_role, entity_type, new_state,
            )
            return False
        logger.info(
            "WorkflowEngine: %s → %s (entity=%s id=%s actor=%s)",
            entity_type, new_state, entity_type, entity_id, actor_role,
        )
        return True

    def get_available_transitions(
        self, entity_type: str, current_state: str, actor_role: str
    ) -> List[str]:
        """Return list of states the actor can transition to from current_state."""
        transitions = self.WORKFLOWS.get(entity_type, self.WORKFLOWS.get("default", []))
        return [
            t.to_state
            for t in transitions
            if t.actor in (actor_role, "Admin", "*")
            and t.from_state in (current_state, "*")
        ]


workflow_engine = WorkflowEngine()
'''

_FALLBACK_BUSINESS_RULES = '''\
"""Business rules and calculation engine — generated by AetherOS (fallback)."""
from __future__ import annotations
import logging
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Dict, Optional

logger = logging.getLogger(__name__)


class BusinessRules:
    """Core business rules and calculation logic for the {domain} domain application {project_name}."""

    # ── Validation rules ──────────────────────────────────────────────────────

    @classmethod
    def validate_positive_amount(cls, amount: float, field_name: str = "amount") -> None:
        """Amount fields must be positive non-zero values."""
        if amount is None or amount <= 0:
            raise ValueError(f"{{field_name}} must be a positive value, got {{amount}}")

    @classmethod
    def validate_non_empty_string(cls, value: str, field_name: str) -> None:
        """String fields must not be empty or whitespace-only."""
        if not value or not value.strip():
            raise ValueError(f"{{field_name}} must not be empty")

    @classmethod
    def validate_percentage(cls, value: float, field_name: str = "percentage") -> None:
        """Percentage values must be between 0 and 100."""
        if value < 0 or value > 100:
            raise ValueError(f"{{field_name}} must be between 0 and 100, got {{value}}")

    # ── Calculation formulas ──────────────────────────────────────────────────

    @classmethod
    def calculate_tax(cls, subtotal: float, tax_rate: float = 0.0) -> float:
        """Calculate tax amount from subtotal and rate (0.0–1.0)."""
        cls.validate_positive_amount(subtotal, "subtotal")
        cls.validate_percentage(tax_rate * 100, "tax_rate (x100)")
        return round(subtotal * tax_rate, 2)

    @classmethod
    def calculate_discount(cls, subtotal: float, discount_rate: float) -> float:
        """Calculate discount amount from subtotal and discount rate (0.0–1.0)."""
        cls.validate_positive_amount(subtotal, "subtotal")
        cls.validate_percentage(discount_rate * 100, "discount_rate (x100)")
        return round(subtotal * discount_rate, 2)

    @classmethod
    def calculate_total(
        cls, subtotal: float, tax_rate: float = 0.0, discount_rate: float = 0.0
    ) -> Dict[str, float]:
        """Calculate order total with tax and discount."""
        cls.validate_positive_amount(subtotal, "subtotal")
        tax = cls.calculate_tax(subtotal, tax_rate)
        discount = cls.calculate_discount(subtotal, discount_rate)
        total = round(subtotal + tax - discount, 2)
        return {{
            "subtotal": subtotal,
            "tax": tax,
            "discount": discount,
            "total": total,
        }}

    # ── Business constraints ─────────────────────────────────────────────────

    @classmethod
    def enforce_max_concurrent(cls, current_count: int, max_allowed: int, resource_name: str) -> None:
        """Enforce maximum concurrent resource limit."""
        if current_count >= max_allowed:
            raise ValueError(
                f"Maximum of {{max_allowed}} concurrent {{resource_name}} reached (current: {{current_count}})"
            )

    @classmethod
    def check_eligibility(cls, data: Dict[str, Any], required_fields: list) -> bool:
        """Check if all required eligibility fields are present and truthy."""
        missing = [f for f in required_fields if not data.get(f)]
        if missing:
            raise ValueError(f"Eligibility check failed: missing required fields: {{', '.join(missing)}}")
        return True


business_rules = BusinessRules()
'''


